import{_ as p,a0 as o,w as l,s as d,ao as r,I as i,x as n,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"命令列技巧：分割文件內容 | LCTT x X-CMD","titleTemplate":false,"description":"命令列技巧：分割文件內容 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列技巧：分割文件內容 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列技巧：分割文件內容 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20190405 Command line quick tips- Cutting content out of files","title":"命令列技巧：分割文件內容","tag":"201905","desc":""},"relativePath":"201905/20190405 Command line quick tips- Cutting content out of files.md","filePath":"[post].md"}'),c={name:"201905/20190405 Command line quick tips- Cutting content out of files.md"};function u(g,s,h,m,f,k){const a=o("Link");return l(),d("div",null,[s[15]||(s[15]=r(`<h1 id="命令列技巧-分割文件內容" tabindex="-1">命令列技巧：分割文件內容 <a class="header-anchor" href="#命令列技巧-分割文件內容" aria-label="Permalink to “命令列技巧：分割文件內容”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/04/commandline-cutting-816x345.jpg" alt=""></p><p>Fedora 發行版是一個功能齊全的操作系統，有出色的圖形化桌面環境。用户可以很容易地通過單擊動作來完成任何典型任務。所有這些美妙的易用性掩蓋了其底層強大的命令列細節。本文是向你展示一些常見命令列實用程序的系列文章的一部分。讓我們進入 shell 來看看 <code>cut</code>。</p><p>通常，當你在命令列中工作時，你處理的是文本文件。有時這些文件可能很長，雖然可以完整地閲讀它們，但是可能會耗費大量時間，並且容易出錯。在本文中，你將學習如何從文本文件中提取內容，並從中獲取你所需的信息。</p><p>重要的是要意識到，在 Fedora 中有許多方法可以完成類似的命令列任務。例如，Fedora 倉庫含有用於解析和處理文本的完整語言系統。此外，還有多個命令列實用程序可用於 shell 中任何可能的用途。本文只關注使用其中幾個實用程序選項，從文件中提取一些信息並以可讀的格式呈現。</p><h3 id="cut-使用" tabindex="-1">cut 使用 <a class="header-anchor" href="#cut-使用" aria-label="Permalink to “cut 使用”">​</a></h3><p>為了演示這個例子，在系統上使用一個標準的大文件，如 <code>/etc/passwd</code>。正如本系列的前一篇文章所示，你可以執行 <code>cat</code> 命令來查看整個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/passwd</span></span>
<span class="line"><span>root:x:0:0:root:/root:/bin/bash</span></span>
<span class="line"><span>bin:x:1:1:bin:/bin:/sbin/nologin</span></span>
<span class="line"><span>daemon:x:2:2:daemon:/sbin:/sbin/nologin</span></span>
<span class="line"><span>adm:x:3:4:adm:/var/adm:/sbin/nologin</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>此文件包含系統上所有所有賬户的信息。它有一個特定的格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>name:password:user-id:group-id:comment:home-directory:shell</span></span></code></pre></div><p>假設你只想要系統上所有賬户名的列表，如果你只能從每一行中刪除 “name” 值。這就是 <code>cut</code> 命令派上用場的地方！它一次處理一行輸入，並提取該行的特定部分。</p><p><code>cut</code> 命令提供了以不同方式選擇一行的部分的選項，在本示例中需要兩個，<code>-d</code> 和 <code>-f</code>。<code>-d</code> 選項允許你聲明用於分隔行中值的分隔符。在本例中，冒號（<code>:</code>）用於分隔值。<code>-f</code> 選項允許你選擇要提取哪些字段值。因此，在本例中，輸入的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cut -d: -f1 /etc/passwd</span></span>
<span class="line"><span>root</span></span>
<span class="line"><span>bin</span></span>
<span class="line"><span>daemon</span></span>
<span class="line"><span>adm</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>太棒了，成功了！但是你將輸出打印到標準輸出，在終端會話中意味着它需要佔據屏幕。如果你需要稍後完成另一項任務所需的信息，這該怎麼辦？如果有辦法將 <code>cut</code> 命令的輸出保存到文本文件中，那就太好了。對於這樣的任務，shell 有一個簡單的內置功能，重定向功能（<code>&gt;</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cut -d: -f1 /etc/passwd &gt; names.txt</span></span></code></pre></div><p>這會將 <code>cut</code> 的輸出放到一個名為 <code>names.txt</code> 的文件中，你可以使用 <code>cat</code> 來查看它的內容:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat names.txt</span></span>
<span class="line"><span>root</span></span>
<span class="line"><span>bin</span></span>
<span class="line"><span>daemon</span></span>
<span class="line"><span>adm</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>使用兩個命令和一個 shell 功能，可以很容易地使用 <code>cat</code> 從一個文件進行識別、提取和重定向一些信息，並將其保存到另一個文件以供以後使用。</p><hr>`,19)),i("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://fedoramagazine.org/command-line-quick-tips-cutting-content-out-of-files/"},{default:t(()=>[...s[0]||(s[0]=[n("https://fedoramagazine.org/command-line-quick-tips-cutting-content-out-of-files/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=n("作者：",-1)),e(a,{href:"https://fedoramagazine.org/author/jakfrost/"},{default:t(()=>[...s[2]||(s[2]=[n("Stephen Snow",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),e(a,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[4]||(s[4]=[n("MjSeven",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const T=p(c,[["render",u]]);export{x as __pageData,T as default};
